\section*{Assumptions}
\begin{assumption}[Smoothness]\label{ass:smooth}
$f:\R^{d}\to\R$ is differentiable and $L$‑smooth, i.e.,
\[
\forall x,y\in\R^{d},\qquad 
f(y)\le f(x)+\inner{\nabla f(x)}{y-x}+\frac{L}{2}\norm{y-x}^{2}.
\]
\end{assumption}
\begin{assumption}[Bounded Stochastic Gradients]\label{ass:bounded}
There exists $G_{\infty}>0$ such that for all $t$,
\[
\|g_t\|_{\infty}\le G_{\infty}\quad\text{almost surely}.
\]
Consequently $0\le v_{t,i}\le G_{\infty}^{2}$ for each coordinate $i$.
\end{assumption}
\begin{assumption}[Stepsize]\label{ass:stepsize}
The learning rates are chosen as
\[
\alpha_t = \frac{\alpha}{\sqrt{t}},\qquad \alpha>0.
\]
\end{assumption}
\begin{assumption}[Decay Parameters]\label{ass:betas}
$\beta_{1},\beta_{2}\in[0,1)$ satisfy $\beta_{1}<\sqrt{\beta_{2}}$ (the standard condition ensuring that the effective stepsizes are non‑increasing).
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}[Convergence of AMSGrad for non‑convex $L$‑smooth objectives]\label{thm:main}
Under Assumptions \ref{ass:smooth}–\ref{ass:betas}, let $\{w_t\}_{t\ge 1}$ be the iterates generated by AMSGrad \eqref{eq:gt}–\eqref{eq:update}.  Define
\[
\bar w_T := \argmin_{t=1,\dots,T}\norm{\nabla f(w_t)}^{2}.
\]
Then for any $T\ge 1$,
\[
\frac{1}{T}\sum_{t=1}^{T}\EE\!\left[\norm{\nabla f(w_t)}^{2}\right]
\;\le\;
\underbrace{\frac{f(w_{1})-f^{\star}}{\alpha(1-\beta_{1})}\sqrt{d}\,G_{\infty}}_{\text{initial gap term}}
\;+\;
\underbrace{\frac{L\alpha G_{\infty}}{(1-\beta_{1})(1-\sqrt{\beta_{2}})}\frac{\log T}{\sqrt{T}}}_{\text{asymptotic rate}}.
\]
Consequently,
\[
\EE\!\left[\norm{\nabla f(\bar w_T)}^{2}\right]=O\!\left(\frac{\log T}{\sqrt{T}}\right).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{enumerate}[label=\arabic*.]
\item \textbf{Stability.} The monotone max operation \eqref{eq:vhat} guarantees that the denominator $\sqrt{\hat v_t^{\text{bias}}}$ never decreases, preventing the effective stepsize from exploding—a failure mode observed for Adam on some pathological problems.
\item \textbf{Hyperparameter Sensitivity.} The bound in Theorem \ref{thm:main} shows an explicit dependence on $\beta_{1}$ and $\beta_{2}$ via the factor $(1-\beta_{1})^{-1}(1-\sqrt{\beta_{2}})^{-1}$.  Small $\beta_{1}$ (fast decay of the first moment) and $\beta_{2}$ not too close to $1$ shrink the constant, but too small $\beta_{2}$ may increase variance of $v_t$.
\item \textbf{Comparison to Baselines.}
    \begin{itemize}
        \item \emph{SGD with diminishing stepsize} achieves $O(1/\sqrt{T})$ for smooth non‑convex problems.  AMSGrad matches this up to a $\log T$ factor while automatically adapting per‑coordinate stepsizes.
        \item \emph{Adam} lacks the monotone $\hat v_t$; without additional assumptions it can diverge (Reddi \emph{et al.}, 2018).  AMSGrad restores a provable guarantee by enforcing \eqref{eq:vhat}.
    \end{itemize}
\end{enumerate}

\section*{Discussion}
The theorem is proved by carefully combining the smoothness descent lemma with a per‑coordinate analysis of the adaptive stepsizes.  The monotonicity of $\hat v_t$ yields a telescoping sum that can be bounded by a logarithmic term, which explains the $\log T$ factor.  In practice the constant factors are often modest, and the algorithm enjoys fast empirical convergence on deep learning tasks despite the worst‑case bound being slightly weaker than that of plain SGD.

