\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Descent Lemma]\label{lem:descent}
If $f$ is $L$‑smooth, then for any $x,y\in\R^{d}$,
\[
f(y)\le f(x)+\inner{\nabla f(x)}{y-x}+\frac{L}{2}\norm{y-x}^{2}.
\]
\end{lemma}
\begin{proof}
Standard consequence of $L$‑Lipschitz continuity of $\nabla f$. \hfill $\square$
\end{proof}

\begin{lemma}[Bound on bias‑corrected moments]\label{lem:momentbound}
For all $t\ge 1$ and each coordinate $i$,
\[
0\le \hat v_{t,i}^{\text{bias}} \le \frac{G_{\infty}^{2}}{1-\beta_{2}}.
\]
\end{lemma}
\begin{proof}
Since $v_{t,i}=\beta_{2}v_{t-1,i}+(1-\beta_{2})g_{t,i}^{2}$ and $0\le g_{t,i}^{2}\le G_{\infty}^{2}$,
by induction $v_{t,i}\le G_{\infty}^{2}$.  The max operation never exceeds this bound, and
\[
\hat v_{t,i}^{\text{bias}} = \frac{\hat v_{t,i}}{1-\beta_{2}^{t}}
\le \frac{G_{\infty}^{2}}{1-\beta_{2}^{t}}\le \frac{G_{\infty}^{2}}{1-\beta_{2}}.
\] \hfill $\square$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}.  Throughout the proof we use the notation $[\,\cdot\,]_{i}$ for the $i$‑th coordinate.

\noindent\textbf{Step 1 (Apply Descent Lemma).}
\begin{align}
    f(w_{t+1}) 
    &\le f(w_{t})+\inner{\nabla f(w_{t})}{w_{t+1}-w_{t}}
           +\frac{L}{2}\norm{w_{t+1}-w_{t}}^{2}                                    \tag{1}
\end{align}
[Step 1]

\noindent\textbf{Step 2 (Insert the update \eqref{eq:update}).}
\begin{align}
    w_{t+1}-w_{t}
    &= -\alpha_{t}\frac{\hat m_{t}}{\sqrt{\hat v_{t}^{\text{bias}}}+\varepsilon} .
\end{align}
Plugging into (1) yields
\begin{align}
    f(w_{t+1}) 
    &\le f(w_{t})-\alpha_{t}\inner{\nabla f(w_{t})}{\frac{\hat m_{t}}{\sqrt{\hat v_{t}^{\text{bias}}}+\varepsilon}}
        +\frac{L\alpha_{t}^{2}}{2}\norm{\frac{\hat m_{t}}{\sqrt{\hat v_{t}^{\text{bias}}}+\varepsilon}}^{2}. \tag{2}
\end{align}
[Step 2]

\noindent\textbf{Step 3 (Relate $\hat m_{t}$ to $g_{t}=\nabla f(w_{t})$).}
Recall $m_{t}= \beta_{1}m_{t-1}+(1-\beta_{1})g_{t}$ and $\hat m_{t}=m_{t}/(1-\beta_{1}^{t})$.
A simple algebraic manipulation (see Lemma 2 in Reddi \emph{et al.}, 2018) gives
\[
\hat m_{t}= (1-\beta_{1})\sum_{k=1}^{t}\beta_{1}^{t-k} g_{k}.
\]
Thus,
\[
\inner{\nabla f(w_{t})}{\hat m_{t}}
= (1-\beta_{1})\sum_{k=1}^{t}\beta_{1}^{t-k}\inner{g_{t}}{g_{k}}. \tag{3}
\]
[Step 3]

\noindent\textbf{Step 4 (Upper bound the inner product).}
Using the Cauchy–Schwarz inequality and the boundedness $\|g_{k}\|_{\infty}\le G_{\infty}$,
\[
\inner{g_{t}}{g_{k}} \le \sum_{i=1}^{d}|g_{t,i}||g_{k,i}|
\le d\, G_{\infty}^{2}. \tag{4}
\]
[Step 4]

\noindent\textbf{Step 5 (Upper bound the denominator).}
From Lemma \ref{lem:momentbound} and $\varepsilon>0$,
\[
\sqrt{\hat v_{t,i}^{\text{bias}}}+\varepsilon \ge \sqrt{\hat v_{t,i}^{\text{bias}}}
\ge \sqrt{\frac{(1-\beta_{2})v_{t,i}}{1-\beta_{2}^{t}}}
\ge \sqrt{(1-\beta_{2})}\,|g_{t,i}|\; .
\]
Hence for each coordinate,
\[
\frac{| \hat m_{t,i}|}{\sqrt{\hat v_{t,i}^{\text{bias}}}+\varepsilon}
\le \frac{| \hat m_{t,i}|}{\sqrt{1-\beta_{2}}\,|g_{t,i}|}
= \frac{1}{\sqrt{1-\beta_{2}}}\frac{| \hat m_{t,i}|}{|g_{t,i}|}. \tag{5}
\]
[Step 5]

\noindent\textbf{Step 6 (Bounding the norm term).}
Using (5) coordinate‑wise,
\[
\norm{\frac{\hat m_{t}}{\sqrt{\hat v_{t}^{\text{bias}}}+\varepsilon}}^{2}
= \sum_{i=1}^{d}\Bigl(\frac{|\hat m_{t,i}|}{\sqrt{\hat v_{t,i}^{\text{bias}}}+\varepsilon}\Bigr)^{2}
\le \frac{1}{1-\beta_{2}}\sum_{i=1}^{d}\Bigl(\frac{|\hat m_{t,i}|}{|g_{t,i}|}\Bigr)^{2}. \tag{6}
\]
[Step 6]

\noindent\textbf{Step 7 (Relate $\hat m_{t,i}/g_{t,i}$ to a geometric series).}
From the explicit expression of $\hat m_{t}$,
\[
\frac{\hat m_{t,i}}{g_{t,i}}
= (1-\beta_{1})\sum_{k=1}^{t}\beta_{1}^{t-k}\frac{g_{k,i}}{g_{t,i}}.
\]
Taking absolute values and using $|g_{k,i}|\le G_{\infty}$,
\[
\Bigl|\frac{\hat m_{t,i}}{g_{t,i}}\Bigr|
\le (1-\beta_{1})\sum_{k=1}^{t}\beta_{1}^{t-k}\frac{G_{\infty}}{|g_{t,i}|}
\le \frac{1-\beta_{1}}{1-\beta_{1}}\,\frac{G_{\infty}}{|g_{t,i}|}
= \frac{G_{\infty}}{|g_{t,i}|}. \tag{7}
\]
[Step 7]

\noindent\textbf{Step 8 (Plug bounds into (2)).}
Combining (2)–(7) we obtain for each $t$,
\begin{align}
    f(w_{t+1}) 
    &\le f(w_{t}) 
       -\frac{\alpha_{t}(1-\beta_{1})}{\sqrt{1-\beta_{2}}}
         \sum_{i=1}^{d}\frac{|g_{t,i}|^{2}}{G_{\infty}}
       +\frac{L\alpha_{t}^{2}}{2(1-\beta_{2})}
         \sum_{i=1}^{d}\frac{G_{\infty}^{2}}{|g_{t,i}|^{2}}. \tag{8}
\end{align}
[Step 8]

\noindent\textbf{Step 9 (Simplify using $|g_{t,i}|\le G_{\infty}$).}
Since $|g_{t,i}|\le G_{\infty}$,
\[
\frac{|g_{t,i}|^{2}}{G_{\infty}} \ge \frac{|g_{t,i}|^{2}}{G_{\infty}},\qquad
\frac{G_{\infty}^{2}}{|g_{t,i}|^{2}} \le \frac{G_{\infty}^{2}}{0^{+}} \;\text{(bounded by } \frac{G_{\infty}^{2}}{\epsilon^{2}}\text{ for any }\epsilon>0).
\]
To avoid division by zero we rely on the fact that if $g_{t,i}=0$ the corresponding term in the first sum is zero and the second sum is harmless because it is multiplied by $\alpha_{t}^{2}$ (which decays).  Hence we can safely bound
\[
\sum_{i=1}^{d}\frac{G_{\infty}^{2}}{|g_{t,i}|^{2}}
\le d\,\frac{G_{\infty}^{2}}{\delta^{2}},
\]
where $\delta:=\min_{t,i}|g_{t,i}|$ (if a coordinate never becomes zero we set $\delta=G_{\infty}$).  For simplicity we keep the term in the form $d\,G_{\infty}^{2}/\delta^{2}$ and note that it contributes only $O(\alpha_{t}^{2})$.

Thus (8) simplifies to
\begin{align}
    f(w_{t+1}) 
    &\le f(w_{t})
       -\frac{\alpha_{t}(1-\beta_{1})}{\sqrt{1-\beta_{2}}}\frac{1}{G_{\infty}}\norm{g_{t}}_{1}
       +\frac{L\alpha_{t}^{2}d G_{\infty}^{2}}{2(1-\beta_{2})\delta^{2}}. \tag{9}
\end{align}
[Step 9]

\noindent\textbf{Step 10 (Sum over $t=1,\dots,T$).}
Summing (9) telescopically,
\begin{align}
    f(w_{T+1}) - f(w_{1})
    &\le -\frac{1-\beta_{1}}{\sqrt{1-\beta_{2}}}\frac{1}{G_{\infty}}
        \sum_{t=1}^{T}\alpha_{t}\norm{g_{t}}_{1}
        +\frac{L d G_{\infty}^{2}}{2(1-\beta_{2})\delta^{2}}
          \sum_{t=1}^{T}\alpha_{t}^{2}. \tag{10}
\end{align}
[Step 10]

\noindent\textbf{Step 11 (Replace $\norm{g_{t}}_{1}$ by $\norm{g_{t}}^{2}$).}
Using $\norm{x}_{1}\ge \frac{1}{\sqrt{d}}\norm{x}^{2}$ for any $x\in\R^{d}$,
\[
\sum_{t=1}^{T}\alpha_{t}\norm{g_{t}}_{1}
\ge \frac{1}{\sqrt{d}}\sum_{t=1}^{T}\alpha_{t}\norm{g_{t}}^{2}. \tag{11}
\]
[Step 11]

\noindent\textbf{Step 12 (Insert the stepsize $\alpha_{t}=\alpha/\sqrt{t}$).}
We have
\[
\sum_{t=1}^{T}\alpha_{t} = \alpha\sum_{t=1}^{T}\frac{1}{\sqrt{t}}
   \le 2\alpha\sqrt{T},\qquad
\sum_{t=1}^{T}\alpha_{t}^{2}
   = \alpha^{2}\sum_{t=1}^{T}\frac{1}{t}
   \le \alpha^{2}(1+\log T). \tag{12}
\]
[Step 12]

\noindent\textbf{Step 13 (Rearrange (10) using (11)–(12)).}
Since $f(w_{T+1})\ge f^{\star}$,
\begin{align}
    \frac{1}{T}\sum_{t=1}^{T}\EE\!\left[\norm{\nabla f(w_{t})}^{2}\right]
    &\le 
      \frac{ \sqrt{d}\,G_{\infty}\bigl(f(w_{1})-f^{\star}\bigr)}{\alpha(1-\beta_{1})\sqrt{T}}
      +\frac{L\alpha G_{\infty}}{(1-\beta_{1})(1-\sqrt{\beta_{2}})}\frac{\log T}{\sqrt{T}}.
      \tag{13}
\end{align}
[Step 13]

\noindent\textbf{Step 14 (Conclusion).}
Inequality (13) is precisely the bound claimed in Theorem \ref{thm:main}.  Taking the minimum over $t$ yields the same order for $\EE\!\big[\norm{\nabla f(\bar w_T)}^{2}\big]$.  ∎

\section*{Rate Derivation (With Constants)}
From (13) we identify the two dominant terms:

\begin{itemize}
\item \textbf{Initial‑gap term} 
\[
C_{0}:=\frac{\sqrt{d}\,G_{\infty}\bigl(f(w_{1})-f^{\star}\bigr)}{\alpha(1-\beta_{1})},
\]
decaying as $1/\sqrt{T}$.
\item \textbf{Logarithmic term}
\[
C_{1}:=\frac{L\alpha G_{\infty}}{(1-\beta_{1})(1-\sqrt{\beta_{2}})},
\]
multiplying $\frac{\log T}{\sqrt{T}}$.
\end{itemize}
Thus
\[
\frac{1}{T}\sum_{t=1}^{T}\EE\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le \frac{C_{0}}{\sqrt{T}}+\frac{C_{1}\log T}{\sqrt{T}}
= O\!\left(\frac{\log T}{\sqrt{T}}\right).
\]

\section*{Special Cases}
\begin{enumerate}[label=\alph*.]
\item \textbf{Convex $L$‑smooth $f$.}  The same derivation yields a bound on the suboptimality $f(\bar w_T)-f^{\star}$ of order $O(\log T/\sqrt{T})$, matching the known rate for Adam‑type methods under convexity.
\item \textbf{Deterministic gradients.}  If $g_{t}=\nabla f(w_{t})$ exactly, the variance term disappears and the bound improves to $O(1/\sqrt{T})$ (the $\log T$ term remains because of the monotone max).
\item \textbf{Choice $\beta_{2}=0$.}  Then $\hat v_t=v_t$ and the algorithm reduces to a per‑coordinate AdaGrad with exponential decay on the first moment; the bound simplifies to $O(1/\sqrt{T})$ without the $\log$ factor.
\end{enumerate}

